window.ScripturaLexicons.BDAG_PART_0329 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-01\" data-source=\"BDAG\" data-search=\"σπιλόω verbo manchar; contaminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπιλόω</td><td>verbo</td><td>manchar; contaminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-02\" data-source=\"BDAG\" data-search=\"σπλαγχνίζομαι verbo compadecer-se; sentir compaixão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπλαγχνίζομαι</td><td>verbo</td><td>compadecer-se; sentir compaixão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-03\" data-source=\"BDAG\" data-search=\"σπλάγχνον, ου, τό substantivo neutro vísceras; coração; afeto; compaixão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπλάγχνον, ου, τό</td><td>substantivo neutro</td><td>vísceras; coração; afeto; compaixão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-04\" data-source=\"BDAG\" data-search=\"σπόγγος, ου, ὁ substantivo masculino esponja BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπόγγος, ου, ὁ</td><td>substantivo masculino</td><td>esponja</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-05\" data-source=\"BDAG\" data-search=\"σποδός, οῦ, ἡ substantivo feminino cinzas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σποδός, οῦ, ἡ</td><td>substantivo feminino</td><td>cinzas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-06\" data-source=\"BDAG\" data-search=\"σπονδίζω verbo oferecer libação; derramar como oferta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπονδίζω</td><td>verbo</td><td>oferecer libação; derramar como oferta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-07\" data-source=\"BDAG\" data-search=\"σπορά, ᾶς, ἡ substantivo feminino semeadura; procriação; semente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπορά, ᾶς, ἡ</td><td>substantivo feminino</td><td>semeadura; procriação; semente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-08\" data-source=\"BDAG\" data-search=\"σπόριμος, ον adjetivo; substantivado semeado; searas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπόριμος, ον</td><td>adjetivo; substantivado</td><td>semeado; searas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-09\" data-source=\"BDAG\" data-search=\"σπόρος, ου, ὁ substantivo masculino semeadura; semente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπόρος, ου, ὁ</td><td>substantivo masculino</td><td>semeadura; semente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-10\" data-source=\"BDAG\" data-search=\"σπουδάζω verbo apressar-se; acelerar; empenhar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπουδάζω</td><td>verbo</td><td>apressar-se; acelerar; empenhar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-11\" data-source=\"BDAG\" data-search=\"σπουδαῖος, α, ον adjetivo solícito; zeloso; diligente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπουδαῖος, α, ον</td><td>adjetivo</td><td>solícito; zeloso; diligente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-12\" data-source=\"BDAG\" data-search=\"σπουδαίως advérbio apressadamente; diligentemente; zelosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπουδαίως</td><td>advérbio</td><td>apressadamente; diligentemente; zelosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-13\" data-source=\"BDAG\" data-search=\"σπουδή, ῆς, ἡ substantivo feminino pressa; rapidez; diligência; zelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπουδή, ῆς, ἡ</td><td>substantivo feminino</td><td>pressa; rapidez; diligência; zelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-14\" data-source=\"BDAG\" data-search=\"σπυρίς, ίδος, ἡ substantivo feminino cesto; cesta grande BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σπυρίς, ίδος, ἡ</td><td>substantivo feminino</td><td>cesto; cesta grande</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-15\" data-source=\"BDAG\" data-search=\"σταγών, όνος, ἡ substantivo feminino gota de água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταγών, όνος, ἡ</td><td>substantivo feminino</td><td>gota de água</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-16\" data-source=\"BDAG\" data-search=\"στάδιον, ου, τό substantivo neutro estádio (medida); arena; estádio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στάδιον, ου, τό</td><td>substantivo neutro</td><td>estádio (medida); arena; estádio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-17\" data-source=\"BDAG\" data-search=\"στάζω verbo instilar; gotejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στάζω</td><td>verbo</td><td>instilar; gotejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-18\" data-source=\"BDAG\" data-search=\"σταθμός, οῦ, ὁ substantivo masculino estação; peso (sentidos incertos) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταθμός, οῦ, ὁ</td><td>substantivo masculino</td><td>estação; peso (sentidos incertos)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-19\" data-source=\"BDAG\" data-search=\"στάμνος, ου substantivo feminino ou masculino jarro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στάμνος, ου</td><td>substantivo feminino ou masculino</td><td>jarro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0329-20\" data-source=\"BDAG\" data-search=\"στασιάζω verbo formar facções; rebelar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στασιάζω</td><td>verbo</td><td>formar facções; rebelar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0329-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπιλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπιλόω</span> part. aor. pass. neut. <span class=\"greek\">σπιλωθέν</span> Wsd 15:4; part. perf. pass. <span class=\"greek\">ἐσπιλωμένος</span> (v. o verbete precedente; Dionys. Hal. et al.; TestAsh 2:7) manchar, contaminar, em nossa lit. somente metaf. (Dositheus 68:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6</a>; Jd 23.—DELG s.v. 2 <span class=\"greek\">σπίλο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπλαγχνίζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπλαγχνίζομαι</span> (<span class=\"greek\">σπλάγχνον</span>; Pr 17:5 A; Ex 2:6 atumano; 1 Km 23:21; Ezk 24:21 Sym.; pseudepígr.; PFlor 296, 23 [VI d.C.].—A at.= át. <span class=\"greek\">σπλαγχνεύω</span> 2 Macc 6:8; a pass. assim em inscr. de Cós [IV a.C.]: ABA 1928, 6 p. 12 n.º 4, 14) dep. pass., 1 fut. <span class=\"greek\">σπλαγχνισθήσομαι</span>; 1 aor. <span class=\"greek\">ἐσπλαγχνίσθην</span> ter piedade, sentir compaixão, talvez <span class=\"greek\">τινός</span> por alguém (B-D-F §176, 1; Rob. 509) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:27</a> (a constr. é duvidosa; <span class=\"greek\">τοῦ</span> <span class=\"greek\">δούλου</span> provavelmente deve antes ser construído com <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>). Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> (B-D-F §235, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:34</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:13</a>; Hs 8, 6, 3; 9, 14, 3; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (B-D-F §233, 2; TestAbr B 12 [Stone p. 80]; TestZeb 7:1; ApcMos 9 p. 116, 31f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:14</a> v.l.; 15:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:34</a>; 8:2; 9:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:13</a> v.l.; Hv 3, 12, 3; m 4, 3, 5; 9:3; Hs 6, 3, 2; 8, 6, 3. Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (B-D-F §229, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:36</a>.—Abs. 18:27 (v. acima); 20:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:33</a>; 15:20; 2 Cl 1:7; Hs 7:4; 8, 11, 1.—DELG s.v. <span class=\"greek\">σπλήν</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπλάγχνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπλάγχνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (v. o verbete precedente; Hom.+, quase sempre pl. <span class=\"greek\">σπλάγχνα</span>, <span class=\"greek\">ων</span>, <span class=\"greek\">τά</span>; inscr., pap., LXX; PsSol 2:14; TestSol 18:29; TestAbr A 3 p. 80, 7 [Stone p. 8]; A 5 p. 80, 20 [St. p. 12]; Test12Patr)</p><p class=\"entry-text\">① as partes internas do corpo, incluindo esp. as vísceras, partes internas, entranhas, lit. (Hom. et al.; inscr.; PRyl 63, 6; 2 Macc 9:5f; 4 Macc 5:30; 10:8; Philo; Jos., Bell. 2, 612) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a> (Appian, Bell. Civ. 2, 99 §410 a respeito do suicídio de Catão <span class=\"greek\">προπεσόντων</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σπλάγχνων</span>).</p><p class=\"entry-text\">② como frequentemente no mundo antigo, as partes internas do corpo serviam de referentes para aspectos psicológicos (v. <span class=\"greek\">καρδία</span>): quanto à sede das emoções, em nosso uso passa-se à tradução coração, fig. (Aeschyl. et al.; Pr 12:10; Sir 30:7; PsSol 2:14; TestAbrA; TestLevi 4:4, al. em Test12Patr; JosAs 6:1; Jos., Bell. 4, 263.—Sobre o ingl. ‘bowels’ neste sentido v. OED s.v. bowel sb. 3), em nossa lit. sobretudo como sede e fonte do amor (assim Herodas 1, 57; Theocr. 7, 99; Dionys. Hal. 11, 35, 4), da compaixão e da misericórdia (não exclusivamente semítico, cf. SEG XXVIII, 541, 14) <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">ἐλέους</span> o coração misericordioso (gen. qualitativo; TestZeb 7:3; 8:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.78\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:78</a>. Também <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">οἰκτιρμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:12</a>. <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἰκτιρμοί</span> afeto e compaixão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (sobre a constr. v. B-D-F §137, 2; Rob. 130; diversamente HNT ad loc.). <span class=\"greek\">τὰ</span> <span class=\"greek\">σπλ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐστιν</span> seu coração se volta para vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:15</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σπλ</span>. <span class=\"greek\">ὑμῶν</span> em vossos próprios corações 6:12. <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> ter compaixão de alguém 1 Cl 23:1. <span class=\"greek\">κλείειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> fechar o coração a alguém necessitado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:17</a>. <span class=\"greek\">ἀναπαύειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σπλ</span>. <span class=\"greek\">τινός</span> (<span class=\"greek\">ἀναπαύω</span> 1) Phlm 20; pass., v. 7.—Sobre <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐνεστερνισμένοι</span> <span class=\"greek\">ἦτε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σπλάγχνοις</span> 1 Cl 2:1 v. <span class=\"greek\">ἐνστερνίζομαι</span>. Por metonímia</p><p class=\"entry-text\">③ do próprio sentimento, pl. amor, afeto (Wsd 10:5; TestZeb 8:2; TestNapht 4:5) <span class=\"greek\">τὰ</span> <span class=\"greek\">σπλ</span>., <span class=\"greek\">ἃ</span> <span class=\"greek\">ἔχετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>. IPhld 10:1. <span class=\"greek\">ἐπιποθεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σπλάγχνοις</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">Ἰ</span>. ansiar por alguém com o afeto de Cristo Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:8</a>.—Amor=o objeto do amor (Artem. 1, 44; 5, 57) <span class=\"greek\">αὐτόν</span>, <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">ἔστιν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐμὰ</span> <span class=\"greek\">σπλ</span>. ele, meu amado Phlm 12 (ou no sentido 2, meu próprio coração).—Sing. (Jos., Ant. 15, 359), fig. (ocasionalmente desde Soph., Aj. 995; BGU 1139, 17 [5 a.C.]) misericórdia, amor <span class=\"greek\">σπλάγχνον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> Hs 9, 24, 2.—B. 1085f. New Docs 3, 84. DELG s.v. <span class=\"greek\">σπλήν</span>. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπόγγος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπόγγος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; PSI 535, 20 [III a.C.]; 558, 7; empréstimo na linguagem rabínica.—Sobre a grafia B-D-F §34, 5; Mlt-H. 109) esponja (Antig. Car. 158 <span class=\"greek\">σπόγγοις</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ξύλοις</span> <span class=\"greek\">δεδεμένοις</span>=[a água é trazida para cima] por meio de esponjas amarradas a varas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σποδός, οῦ, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σποδός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ἡ</span> (Hom. et al.; inscr., LXX, TestJob, TestJos 15:2; Jos., Ant. 20, 89; 123; Just., D. 92, 2) cinzas, com <span class=\"greek\">γῆ</span> como designação de algo transitório 1 C1 17:2 (Gen 18:27). Sobre seu emprego com <span class=\"greek\">σάκκος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:13</a>; B 3:2; 7:5 v. <span class=\"greek\">σάκκος</span>. As cinzas da novilha vermelha (Num 19:9; v. IScheftelowitz, Das Opfer der Roten Kuh [Num 19]: ZAW 39, 1924, 113–23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:13</a>; B 8:1.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπονδίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπονδίζω</span> (derivado de <span class=\"greek\">σπονδή</span>; = gr. anterior <span class=\"greek\">σπένδω</span>) 1 aor. pass. <span class=\"greek\">ἐσπονδίσθην</span> oferecer uma libação/oferta de bebida, derramar (como oferta) pass. IRo 2:2.—DELG s.v. <span class=\"greek\">σπένδω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπορά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπορά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">σπείρω</span> e os dois verbetes seguintes; Aeschyl. et al.; inscr., pap., LXX; TestSol 5:3 P; TestReub 2:8; Philo, Joseph., Just.; Tat. 11, 1; Ath. 22, 6 e R. 1 p. 48, 6) prim. ‘a atividade de semear’ e fig. ‘procriação’, depois por metonímia ‘aquilo que é semeado’ (Eur., Andr. 637; pap.; 1 Macc 10:30; Jos., Ant. 2, 306), donde passa também a significar semente (SIG 826c, 15 [117 a.C.] <span class=\"greek\">μήτε</span> <span class=\"greek\">σπορῶν</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">καρπῶν</span>; Herm. Wr. 13:2; PGM 1, 32; 13, 176), sentido geralmente aceito para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:23</a> (cf. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σπορά</span> Ps.-Callisth. 1, 10; 13), embora ESelwyn, 1 Pt ’46, 307 prefira origem ou semeadura.—DELG s.v. <span class=\"greek\">σπείρω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπόριμος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπόριμος</span>, <span class=\"greek\">ον</span> (v. <span class=\"greek\">σπείρω</span>, <span class=\"greek\">σπορά</span> e <span class=\"greek\">σπόρο</span>; X. et al.; IG XII, 3, 344; 345; pap., LXX) relativo ao que foi semeado, semeado, subst. <span class=\"greek\">τὰ</span> <span class=\"greek\">σπόριμα</span> cereal em pé, campos de cereais (Ps.-Aeschines, Ep. 9, 1; SibOr 8, 181; Geopon. 1, 12, 37; PLond II, 413, 14f p. 302 <span class=\"greek\">ἐπιδὴ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δορκάδια</span> <span class=\"greek\">ἀφανίζουσειν</span> <span class=\"greek\">τὸ</span> [leia-se <span class=\"greek\">τὰ</span>] <span class=\"greek\">σπόριμα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:1</a>.—BMurmelstein, Jesu Gang durch d. Saatfelder: <span class=\"greek\">Αγγελος</span> III, 1930, 111–20.—DELG s.v. <span class=\"greek\">σπείρω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπόρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπόρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. <span class=\"greek\">σπείρω</span> e os dois verbetes precedentes)</p><p class=\"entry-text\">① o processo de semear, semeadura (Hdt. et al.; inscr., pap.; Philo, Fuga 171; Jos., Ant. 18, 272) 1 Cl 24:4; AcPlCor 2:26.</p><p class=\"entry-text\">② o caroço do fruto, semente (Apollon. Rhod. 3, 413; 498; Theocr. 25, 25; Diod S 5, 68, 2; Plut., Mor. 670b; pap., LXX; En 10:19; Philo; ApcEsdr 5:12 p. 30, 6 Tdf.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:11</a>. <span class=\"greek\">βάλλειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σπ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:26</a>. Também <span class=\"greek\">σπεῖραι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σπ</span>. (cf. Dt 11:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a> (sobre a parábola v. GHarder, Theologia Viatorum, ’48/49, 51–70; JJeremias, NTS 13, ’66, 48–53. Sobre o filósofo como semeador de sementes, AHenrichs, ZPE 1, ’67, 50–53). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:10a</a> v.l.—Em imagem <span class=\"greek\">πληθυνεῖ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σπόρον</span> <span class=\"greek\">ὑμῶν</span> ele aumentará vossa provisão de sementes (i.e., vossa provisão de coisas a distribuir aos necessitados) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:10b</a>. Texto incerto AcPl BMM verso 25 <span class=\"greek\">σπό̣</span>[<span class=\"greek\">ρον</span>].—DELG s.v. <span class=\"greek\">σπείρω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπουδάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπουδάζω</span> (v. os três verbetes seguintes; Soph., X., Pla.+; inscr., pap., LXX, Test12Patr, Philo, Joseph., apolog.) fut. <span class=\"greek\">σπουδάσω</span> (Polyb. 3, 5, 8; Diod S 1, 58, 4; EpArist 10; Jos., Ant. 17, 203; B-D-F §77; Mlt-H. 259); 1 aor. <span class=\"greek\">ἐσπούδασα</span>; perf. <span class=\"greek\">ἐσπούδακα</span> Job 21:6; 23:15.</p><p class=\"entry-text\">① proceder rapidamente, apressar-se, dar-se pressa, seguido de inf. (Jdth 13:12 <span class=\"greek\">ἐσπούδασαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καταβῆναι</span>; ParJer 5:5 <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐσπούδαζεν</span> se ele não estivesse com pressa; Jos., Ant. 8, 202 <span class=\"greek\">σπ</span>. <span class=\"greek\">καταλιπεῖν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:9</a>, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:12</a>; IEph 1:2. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">σπουδάζειν</span>, <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἅψηται</span> porque cada um se apressava a tocar MPol 13:2. Mas o sentido 3 também é aceitável em todos esses lugares.</p><p class=\"entry-text\">② acelerar um processo, apressar, com ac. <span class=\"greek\">τὰ</span> <span class=\"greek\">θηριομαχία</span> os combates com animais selvagens (lat. ludus bestiariorum) AcPl Ha 2, 11.</p><p class=\"entry-text\">③ ser especialmente consciencioso no cumprimento de uma obrigação, ser zeloso/solícito, esmerar-se, envidar todo esforço, ser consciencioso, seguido de inf. (X., Ap. 22; Diod S 1, 58, 4; Herodian 1, 1, 1; Jos., Ant. 17, 203, C. Ap. 1, 116; TestDan 6:3; TestNapht 3:1; Ar. 15, 5; Just., A II, 8, 2; Mel., HE 4, 26, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:10</a>; 3:14; 2 Cl 10:2; 18:2; B 1:5; 4:9; 21:9; IEph 5:3; 10:2; 13:1; IMg 6:1; 13:1; IPhld 4. Seguido de ac. e inf. (BGU 1080, 14; PFlor 89, 11 e13; 131) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:15</a>. Com nom. e inf. (Epict. 2, 22, 34) IEph 10:3 (B-D-F 392, 1a; Rob. 1077f).—<span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> a respeito de algo (Ath., R. 14 p. 64, 21) e <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <span class=\"greek\">ἵνα</span> de um benfeitor, preocupar-se com alguém, de modo que Hs 2, 6. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>: <span class=\"greek\">σπουδάζετε</span> <span class=\"greek\">ἐπὶ</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> AcPl Ha 6, 18=‘sede solícitos por … [texto corrompido] e por demonstrar afeto’.—V. Larfeld no verbete <span class=\"greek\">σπουδή</span>. DELG s.v. <span class=\"greek\">σπεύδω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπουδαῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπουδαῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (v. <span class=\"greek\">σπουδάζω</span> e os dois verbetes seguintes; <span class=\"greek\">σπουδή</span>; Pind., Hdt.+; inscr., pap.; Ezk 41:25 [<span class=\"greek\">σπουδαῖα</span> <span class=\"greek\">ξύλα</span>]; TestJud 1:4. Freq. em Philo. Jos., Ant. 6, 296 v.l., C. Ap. 1, 214; apolog. exc. Ar.) comum na lit. e nas inscr. com ref. a um sentido excepcional de responsabilidade cívica ou <span class=\"greek\">ἀρετή</span> (cf. Arist., Poetics 1448a; JSmithson, The Moral View of Aristotle’s ‘Poetics’: Journal of the History of Ideas 44, ’83, 3–17; <span class=\"greek\">σπουδή</span> 2) relativo a ser consciencioso no cumprimento de um dever ou obrigação, solícito, zeloso, empenhado, diligente <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:22a</a>; <span class=\"greek\">σπ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> empenhado com solicitude em algo Hv 3, 1, 2. <span class=\"greek\">πλέον</span> <span class=\"greek\">σπουδαῖος</span> ainda mais diligente IPol 3:2.—Comp. <span class=\"greek\">σπουδαιότερος</span> muito empenhado (B-D-F §244, 2; cf. ILegesSacr II, 7, 34 [III d.C.] <span class=\"greek\">εὐσεβέστερος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:17</a>. <span class=\"greek\">πολὺ</span> <span class=\"greek\">σπουδαιότερος</span> muito mais zeloso v. 22b.—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:17</a> v.l., v. <span class=\"greek\">σπουδαίως</span> 2.—DELG s.v. <span class=\"greek\">σπεύδω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπουδαίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπουδαίως</span> adv. de <span class=\"greek\">σπουδαῖος</span> (X., Pla., Aristot. et al.; PSI 742, 6; Wsd 2:6; TestSol 22:11; Joseph.)</p><p class=\"entry-text\">① relativo a ser rápido em fazer algo, com pressa, com ênfase na importância daquilo que se faz (Pollux 3, 149) comp. <span class=\"greek\">σπουδαιοτέρως</span> com especial urgência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:28</a>.</p><p class=\"entry-text\">② relativo a ser consciencioso no cumprimento de um dever ou obrigação, diligentemente, com empenho, zelosamente (Diog. L. 6, 27; Jos., Ant. 8, 6; inscr.: SEG XL, 1770, 16f [196/97 d.C. Chr.]; CB I/2 n.º 480, com <span class=\"greek\">πιστῶς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a>. <span class=\"greek\">παρακαλεῖν</span> <span class=\"greek\">σπ</span>. instar energicamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:4</a>.—Comp. com muita solicitude <span class=\"greek\">σπουδαιότερον</span> (Pla., Rep. 7, 536c; Jos., Ant. 16, 85; Tat. 33, 2 [com gen. de comparação]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:17</a> v.l.; <span class=\"greek\">σπουδαιοτέρως</span> (Ps.-Plut., Nobil. 15, ed. Bern. VII 252, 15) ibid. v.l.—DELG s.v. <span class=\"greek\">σπεύδω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπουδή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπουδή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (v. os três verbetes precedentes; Hom.+)</p><p class=\"entry-text\">① rapidez de movimento ou ação, pressa, celeridade <span class=\"greek\">μετὰ</span> <span class=\"greek\">σπουδῆς</span> com pressa, apressadamente (Appian, Iber. 27 §105; 28 §110; Polyb. 1, 27, 8; Herodian 3, 4, 1; 6, 4, 3; PTebt 315, 8 [II d.C.]; Ex 12:11; Wsd 19:2; JosAs 28:8 cód. A [p. 83, 9 Bat.]; Jos., Ant. 7, 223) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:39</a> (BHospodar, CBQ 18, ’56, 14–18 [‘seriamente’]); MPol 8:3 v.l.</p><p class=\"entry-text\">② empenho sincero no cumprimento de uma obrigação ou na vivência de uma relação, solicitude, empenho, diligência, disposição, zelo, freq. na lit. e nas inscr. greco-romanas, de dedicação extraordinária às responsabilidades cívicas e religiosas, que estavam freq. entrelaçadas, e também de preocupação com a excelência moral pessoal ou com a máxima dedicação aos interesses alheios (IMagnMai 53, 61; 85, 12 e 16; v. Thieme, p. 31; Larfeld I 499f; Danker, Benefactor 320f; Herm. Wr. 2, 17 <span class=\"greek\">σπουδὴ</span> <span class=\"greek\">εὐσεβεστάτη</span>; Jos., Ant. 13, 245; Just., D. 9, 3; Mel., HE 4, 26, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:11</a>; 8:7, 8 (gen. subj.). <span class=\"greek\">μετὰ</span> <span class=\"greek\">σπουδῆς</span> diligentemente, atentamente (Ps.-Aristot., De Mundo 1; SIG 611, 5; UPZ 110, 131 [164 a.C.]; 3 Macc 5:24, 27; Philo; Jos., C. Ap. 2, 42) Dg 12:1. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">σπ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a>. <span class=\"greek\">σπ</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> boa vontade para com alguém, dedicação a alguém (cf. Philo, Leg. ad Gai. 242) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:12</a>; 8:16. <span class=\"greek\">ἐνδείκνυσθαι</span> <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> demonstrar empenho em algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a> (cf. Philo, Somn. 2, 67; Jos., Ant. 12, 134; Ath. 3, 2). <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">παρεισενέγκαντες</span> <span class=\"greek\">ἐπιχορηγήσατε</span> envidai todo esforço para acrescentar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a> (<span class=\"greek\">πᾶσα</span> <span class=\"greek\">σπ</span>., uma formulação freq. em decretos cívicos [v. os índices em vários corpora de inscr.]; também, inter alia, PTebt I, 33, 18f; Philo, Leg. ad Gai. 338, Sacr. Abel. 68); <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σπ</span>. <span class=\"greek\">ποιεῖσθαι</span> (v. <span class=\"greek\">ποιέω</span> 7a) mostrar grande solicitude, seguido de inf. (Philostrat., Ep. 1) Jd 3; <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">εἰσήγησε</span> (=<span class=\"greek\">εἰσήγησαι</span>) <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">παραγενέσθαι</span> <span class=\"greek\">ἐνθάδε</span> envida todo esforço para vir aqui AcPlCor 1:16. <span class=\"greek\">σπουδὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">συλληφθῆναι</span> <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">ἄνδρα</span> MPol 7:2.—DELG s.v. <span class=\"greek\">σπεύδω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σπυρίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σπυρίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (Hdt., Aristoph. et al.; pap.; Philo, Spec. Leg. 3, 160; sobre a forma <span class=\"greek\">σφυρίς</span>, também atestada, v. Schwyzer I 161; B-D-F §34, 5; W-S. §5, 27e; Mlt-H. 109; Mayser 173; Dssm., B 157, NB 13 [BS 158; 185]) cesto, cesta grande <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:25</a>. Em conexão com o milagre da multiplicação dos alimentos (como cesta para comestíveis: Hdt. 5, 16; Epict. 4, 10, 21; Athen. 8, 365a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:37</a>; 16:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:8</a>, 20.—V. <span class=\"greek\">κόφινος</span>.—B. 623. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταγών, όνος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταγών</span>, <span class=\"greek\">όνος</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hippocr.+; inscr., LXX) gota de água Hm 11:20.—B. 672. DELG s.v. <span class=\"greek\">στάζω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στάδιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στάδιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Jos., Ant. 15, 415; Just., D. 9, 3) pl. <span class=\"greek\">τὰ</span> <span class=\"greek\">στάδια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a> v.l.; Hv 4, 1, 2 e <span class=\"greek\">οἱ</span> <span class=\"greek\">στάδιοι</span> (TestAbrB 2 p. 106, 20 [Stone p. 60]; TestZeb 7:4; TestGad; Just., A I, 34, 2; ambos os plurais também no gr. át.; v. Kühner-Bl. I 500; B-D-F §49, 3; W-S. §8, 12; Mlt-H. 122; Mayser 289; Thackeray 155; Helbing 46f; Reinhold 53f)</p><p class=\"entry-text\">① medida de distância de cerca de 192 metros, estádio, um oitavo de milha (Hdt. et al.; inscr., pap.; Da 4:12; 2 Macc; pseudepígr.; Jos., Bell. 5, 192 <span class=\"greek\">ἓξ</span> <span class=\"greek\">σταδίους</span>; 7, 284, Ant. 18, 60; Just., A I, 34, 2) = com margem para variações segundo a localidade, 600 pés gregos (625 romanos; c. 607 ingleses)=192 metros. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:13</a> (para a v.l. cf. Appian, Bell. Civ. 5, 35 §140 <span class=\"greek\">ἑξήκοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἑκατὸν</span> <span class=\"greek\">σταδίους</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a>; 11:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:20</a>; 21:16; Hv 4, 1, 2; 5.—V. ASegré, JBL 64, ’45, 369–71.</p><p class=\"entry-text\">② área para espetáculos públicos, arena, estádio (Pind. et al.; inscr., pap.; Philo, Op. M. 78; Jos., Bell. 2, 172, Vi. 331 <span class=\"greek\">τὸ</span> <span class=\"greek\">στ</span>.; empréstimo no rabínico), sobre a qual ou na qual se realizavam corridas a pé e outras competições atléticas públicas MPol 6:2; 8:3; 9:1f; 12:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τρέχειν</span> disputar uma corrida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24</a>. <span class=\"greek\">ἔξω</span> <span class=\"greek\">βάλλεσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στ</span>. ser expulso do estádio 2 Cl 7:4 (v. <span class=\"greek\">μαστιγόω</span> 1a). Abs. arena para combates com animais AcPl Ha 2, 5 (restaurado); 4, 11 e 13; 5, 14.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στάζω</span> 1 aor. <span class=\"greek\">ἔσταξα</span></p><p class=\"entry-text\">① fazer cair gota a gota (Hom.+; LXX; PsSol 17:18; ParJer), em imagem da atividade divina, instilar <span class=\"greek\">στ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">δικαιοσύνην</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> instilar justiça em alguém Hv 3, 9, 1.</p><p class=\"entry-text\">② cair gota a gota, gotejar, escorrer, intr. (desde Trag.; Hdt. 6, 74; Hippocr.; LXX; SibOr 5, 373) B 12:1 (cit. de origem incerta).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταθμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταθμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; inscr., pap., LXX; PsSol 5:4; TestNapht 2:3; Philo, Rer. Div. Her. 144; Just., D. 111, 3 e Mel., P. 14, 90 batentes de porta) o sentido em <span class=\"greek\">ἀνέμων</span> <span class=\"greek\">σταθμοί</span> 1 Cl 20:10 é incerto; pode ser: estação (?—assim Polyaenus 5, 8, 1; Jos., Bell. 1, 308) ou peso (?—assim Jos., C. Ap. 2, 216; cf. Job 28:25).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στάμνος, ου</h1><div class=\"entry-meta\"><span>substantivo feminino ou masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στάμνος</span>, <span class=\"greek\">ου</span> (Aristoph. et al.; inscr., pap., LXX), <span class=\"greek\">ἡ</span> (assim no gr. át.; mas <span class=\"greek\">ὁ</span> no dórico e na LXX: B-D-F §49, 1; Thackeray p. 146; nota sobre PHamb 10, 35; Mlt-H. 124) jarro, no qual se conservava o maná (Ex 16:33; Philo, Congr. Erud. Grat. 100) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0329-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στασιάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στασιάζω</span> 1 aor. <span class=\"greek\">ἐστασίασα</span> (v. os dois verbetes seguintes; Aristoph., Hdt.+; inscr., LXX; Jos., Bell. 5, 248, Ant. 17, 27; Acta Alex. XVIII, col. 2, 14) agir de modo faccioso e provocar discórdia pública, rebelar-se <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> contra alguém (X., An. 6, 1, 29, Hell. 1, 1, 28; Pla., Rep. 8, 545d; 566a al.; v. Jos., Ant. 1, 110; 13, 74) 1 Cl 4:12; 46:7; 47:6; 51:3. Abs. (Menand., Epitr. 641 J.; Diod S 18, 39, 3; Polyaenus 5, 26; 8, 23, 21; Oenomaus em Eus., PE 5, 28, 8; Philo, Op. M. 33) 43:2; 49:5; 55:1.—DELG s.v. <span class=\"greek\">στάσις</span>.</p></section></article>"};
